svg.script:

(function() {
  var root = document.getElementById('a12p3b-svg');
  if (!root) return;

  var btnSinfise = document.getElementById('a12p3b-btn-sinfise');
  var btnPromontorio = document.getElementById('a12p3b-btn-promontorio');
  var btnEspinhas = document.getElementById('a12p3b-btn-espinhas');

  function setActiveAnchor(anchorKey) {
    root.setAttribute('data-active-anchor', anchorKey);

    if (btnSinfise) btnSinfise.setAttribute('aria-pressed', anchorKey === 'sinfise' ? 'true' : 'false');
    if (btnPromontorio) btnPromontorio.setAttribute('aria-pressed', anchorKey === 'promontorio' ? 'true' : 'false');
    if (btnEspinhas) btnEspinhas.setAttribute('aria-pressed', anchorKey === 'espinhas' ? 'true' : 'false');
  }

  function attachHandler(el, key) {
    if (!el) return;
    el.addEventListener('click', function(e) {
      e.preventDefault();
      setActiveAnchor(key);
    });
    el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ' || e.keyCode === 13 || e.keyCode === 32) {
        e.preventDefault();
        setActiveAnchor(key);
      }
    });
  }

  attachHandler(btnSinfise, 'sinfise');
  attachHandler(btnPromontorio, 'promontorio');
  attachHandler(btnEspinhas, 'espinhas');
})();
